class Solution {
  private static final long MOD = 1_000_000_007L;

  public int totalBeauty(int[] nums) {
    int n = nums.length, max = 0;
    for (int v : nums) max = Math.max(max, v);
    int[] cnt = new int[max + 2];
    for (int v : nums) {
      for (int d = 1; (long) d * d <= v; d++) {
        if (v % d != 0) continue;
        cnt[d]++;
        if (d != v / d) cnt[v / d]++;
      }
    }
    int[] startIdx = new int[max + 2];
    for (int g = 1; g <= max; g++) startIdx[g + 1] = startIdx[g] + cnt[g];
    int[] fill = new int[max + 2], list = new int[startIdx[max + 1]];
    for (int i = 0; i < n; i++) {
      int v = nums[i];
      for (int d = 1; (long) d * d <= v; d++) {
        if (v % d != 0) continue;
        list[startIdx[d] + fill[d]++] = i;
        if (d != v / d) list[startIdx[v / d] + fill[v / d]++] = i;
      }
    }
    long[] exact = new long[max + 1];
    long[] bit = new long[max + 2];
    for (int g = max; g >= 1; g--) {
      int from = startIdx[g], to = startIdx[g + 1];
      long total = 0;
      if (to > from) {
        int size = max / g + 1;
        java.util.Arrays.fill(bit, 0, size + 1, 0);
        for (int p = from; p < to; p++) {
          int idx = nums[list[p]] / g;
          long dp = 1;
          for (int i = idx - 1; i > 0; i -= i & -i) dp += bit[i];
          dp %= MOD;
          for (int i = idx; i <= size; i += i & -i) bit[i] = (bit[i] + dp) % MOD;
          total += dp;
        }
        total %= MOD;
      }
      for (int m = 2 * g; m <= max; m += g) total -= exact[m];
      exact[g] = ((total % MOD) + MOD) % MOD;
    }
    long ans = 0;
    for (int g = 1; g <= max; g++) ans = (ans + g * exact[g]) % MOD;
    return (int) ans;
  }
}
